/**
 * /developers/docs/<section>/llms.txt: scoped agent indexes.
 * The old /docs/<section>/llms.txt redirects here (docsPrefixMoveRedirects).
 *
 * The bodies are generated by `gen:llms` into
 * packages/docs-tooling/generated/llms-sections/<section>.txt and baked in at
 * build time (force-static), so the deployed function never reads the repo.
 * The middleware (src/proxy.ts) passes file paths under the docs through
 * without the locale rewrite, so the request reaches this route.
 */
import {
  listLlmsSections,
  readLlmsSection,
} from "@/lib/docs-edge/llms-sections";

export const dynamic = "force-static";
export const dynamicParams = false;

export function generateStaticParams() {
  return listLlmsSections().map((section) => ({ section }));
}

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ section: string }> },
) {
  const { section } = await params;
  const body = readLlmsSection(section);

  if (body === null) {
    return new Response("Not Found", { status: 404 });
  }

  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, s-maxage=3600, stale-while-revalidate=86400",
    },
  });
}
